mapper.select:
SELECT sydbi.*, pyp.code as productCode, pyp.id as product_id, (select name from sto_yt_location where id= sydbi.location_id) as locationName, syos.order_id as orderId, syos.id as orderSubId, sdi.order_sub_item_id as orderSubItemId, sdi.category_specification_item_id as categorySpecificationItemId, sdi.category_specification_item_name as categorySpecificationItemName FROM sto_yt_delivery_box_item as sydbi left join pro_yt_product_specification as pyps on sydbi.specification_id = pyps.id left join pro_yt_product as pyp on pyp.id = pyps.product_id left join sto_yt_delivery_box as sydb on sydb.id = sydbi.delivery_box_id left join sto_yt_delivery as syd on syd.id = sydb.delivery_id left join sto_yt_delivery_item as sdi on sdi.delivery_id = syd.id and sdi.specification_id = sydbi.specification_id left join sal_yt_order_sub as syos on syos.id = sdi.order_sub_id WHERE syos.order_id IN
#{orderId}
AND sydbi.is_deleted = 0 AND sdi.is_deleted = 0
